const html = $json.body;
const yachts = [];

// Parse yacht cards from HTML
// This regex pattern extracts yacht data from the brokers page
const yachtPattern = /<div[^>]*class="[^"]*yacht-card[^"]*"[^>]*>[\s\S]*?<\/div>/gi;
const matches = html.match(yachtPattern) || [];

for (const match of matches) {
  // Extract slug from links
  const slugMatch = match.match(/href="[^"]*\/([a-z0-9-]+)"/);
  const titleMatch = match.match(/<h[23][^>]*>([^<]+)<\/h[23]>/);
  const locationMatch = match.match(/location[^>]*>([^<]+)</);

  if (slugMatch) {
    yachts.push({
      yacht_id: slugMatch[1],
      title: titleMatch ? titleMatch[1].trim() : slugMatch[1],
      location: locationMatch ? locationMatch[1].trim() : 'Miami',
      calendar_url: `http://calendar.ycn.miami/${slugMatch[1]}`,
      media_url: `http://media.ycn.miami/${slugMatch[1]}`,
      status: 'active',
      synced_at: new Date().toISOString()
    });
  }
}

return yachts;
}}

