// Alternative HTML parsing with more robust extraction
const html = $input.first().json.body || '';
const yachts = [];

// Try multiple selectors/patterns
const patterns = [
  // Pattern 1: Look for yacht links
  /href="(?:https?:\/\/)?(?:www\.)?ycn\.miami\/yacht\/([a-z0-9-]+)"/gi,
  // Pattern 2: Look for calendar links
  /calendar\.ycn\.miami\/([a-z0-9-]+)/gi,
  // Pattern 3: Look for media links  
  /media\.ycn\.miami\/([a-z0-9-]+)/gi
];

const foundSlugs = new Set();

for (const pattern of patterns) {
  let match;
  while ((match = pattern.exec(html)) !== null) {
    foundSlugs.add(match[1]);
  }
}

// Convert to yacht objects
for (const slug of foundSlugs) {
  yachts.push({
    yacht_id: slug,
    title: slug.split('-').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' '),
    location: 'Miami',
    calendar_url: `http://calendar.ycn.miami/${slug}`,
    media_url: `http://media.ycn.miami/${slug}`,
    drive_folder_id: null,
    status: 'active',
    synced_at: new Date().toISOString()
  });
}

return yachts.map(y => ({ json: y }));
